#if OPENNET_TESTING
using System;
using System.IO;
using System.Linq;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Controls;
using NetworkHub.App;
namespace NetworkHub.Desktop;
internal static class TestsR5
{
 static void Check(bool ok,string message){if(!ok)throw new Exception(message);}
 static async Task Click(Shell shell,string name){shell.Find<CheckBox>(name).RaiseEvent(new RoutedEventArgs(System.Windows.Controls.Primitives.ButtonBase.ClickEvent));for(int i=0;i<200&&shell.Workspace.Switching;i++)await Task.Delay(25);Check(!shell.Workspace.Switching,"Switch did not complete");}
 internal static async Task Ui(Shell shell,AppFiles files,Func<string,Func<Task>,Task> test)
 {
  await test("External switch explains ownership without stopping a foreign process",async()=>{
   var timer=new System.Windows.Threading.DispatcherTimer{Interval=TimeSpan.FromMilliseconds(25)};bool explained=false;
   try{
    await shell.StopSelected(true);int launches=shell.Runtime.LaunchCount;
    shell.Runtime.ObservationForTests=id=>id=="tg"?new(id,ObservedState.External,"external fixture",123):null;await shell.Refresh();
    timer.Tick+=(_,_)=>{var dialog=shell.Window.OwnedWindows.Cast<Window>().FirstOrDefault(w=>w.Title=="TG WS Proxy");if(dialog==null)return;explained=LocalizedTree.Walk(dialog).OfType<TextBlock>().Any(t=>t.Text.Contains(L.T("This tool is running outside this copy of Open Net. To control it here, first close it using the application or tray that started it, then turn it on here. The running process has been left unchanged.")));dialog.UpdateLayout();TestsR2.Capture((FrameworkElement)dialog.Content,Path.Combine(files.Data,"switch-external-explanation.png"));dialog.DialogResult=true;timer.Stop();};timer.Start();
    typeof(System.Windows.Controls.Primitives.ToggleButton).GetMethod("OnClick",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic)!.Invoke(shell.Find<CheckBox>("TgCheck"),null);
    for(int i=0;i<200&&shell.Workspace.Switching;i++)await Task.Delay(25);
    Check(explained&&!shell.Workspace.Switching,"No visible external-instance explanation");Check(shell.Runtime.LaunchCount==launches&&shell.Workspace.ToolOn("tg")&&shell.Find<CheckBox>("TgCheck").IsChecked==true,"Foreign state changed");
   }finally{timer.Stop();shell.Runtime.ObservationForTests=null;await shell.Refresh();}
  });
  await test("DNS switch opens unavailable adapter setup without writing",async()=>{
   var isolated=new AppFiles(Path.Combine(files.Root,"test-results/missing-switch-adapter-"+Guid.NewGuid().ToString("N")));using var instance=new SingleInstance(isolated.Data,isolated.Log);var fake=TestsDns.Fixture(isolated.Data);HbDnsController.ReaderForTests=fake;var preview=new Shell(isolated,true,instance);
   try{
    preview.Settings.HbDnsAdapterId=Guid.NewGuid().ToString("D");preview.Window.Show();await preview.Refresh();await preview.Workspace.ToggleTool("dns",true);
    var view=(SimpleDnsView)typeof(Shell).GetField("dnsWindow",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic)!.GetValue(preview)!;
    Check(view.Window.IsVisible&&fake.Writes==0&&preview.Find<CheckBox>("DnsCheck").IsChecked==false,"Missing adapter produced no visible setup or wrote DNS");
    view.Window.UpdateLayout();TestsR2.Capture((FrameworkElement)view.Window.Content,Path.Combine(files.Data,"switch-dns-adapter-setup.png"));((ComboBox)view.Window.FindName("HbAdapter")).SelectedIndex=0;Check(fake.Writes==0,"Adapter selection wrote DNS");view.ConfirmationForTests=_=>true;
    await preview.Workspace.ToggleTool("dns",true);Check(fake.Writes==1&&preview.DnsApplied,"Configured mock switch could not turn on");await preview.Workspace.ToggleTool("dns",false);Check(fake.State.IPv4.Mode==NetworkHub.Dns.DnsMode.Automatic,"Mock switch could not turn off");view.Window.Close();
   }finally{preview.Dispose();preview.Window.Close();HbDnsController.ReaderForTests=null;shell.ApplySettings(shell.Settings.Copy());}
  });
  await test("Switch framework OnClick toggles before dispatching the operation",async()=>{var saved=shell.Settings.Copy();try{await shell.StopSelected(true);shell.Settings.ConfirmStartStop=false;await shell.Refresh();var toggle=shell.Find<CheckBox>("TgCheck");Check(toggle.IsChecked==false,"Initial toggle state");typeof(System.Windows.Controls.Primitives.ToggleButton).GetMethod("OnClick",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic)!.Invoke(toggle,null);for(int i=0;i<200&&shell.Workspace.Switching;i++)await Task.Delay(25);Check(shell.Workspace.ToolOn("tg")&&toggle.IsChecked==true,"Framework click did not start stub");typeof(System.Windows.Controls.Primitives.ToggleButton).GetMethod("OnClick",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic)!.Invoke(toggle,null);for(int i=0;i<200&&shell.Workspace.Switching;i++)await Task.Delay(25);Check(!shell.Workspace.ToolOn("tg")&&toggle.IsChecked==false,"Framework click did not stop stub");}finally{await shell.StopSelected(true);shell.ApplySettings(saved);}});
  await test("R5 individual switches operate owned stubs independently of group and startup",async()=>{var saved=shell.Settings.Copy();try{await shell.StopSelected(true);var next=saved.Copy();next.ZapretSelected=false;next.TgSelected=false;next.StartupZapret=false;next.StartupTg=true;next.ConfirmStartStop=true;next.Language="ru";next.Backdrop="solid";shell.ApplySettings(next);await shell.Refresh();shell.RoutineConfirmationForTests=_=>false;shell.Find<CheckBox>("ZapretCheck").IsChecked=true;await Click(shell,"ZapretCheck");Check(!shell.Find<CheckBox>("ZapretCheck").IsChecked!.Value&&!shell.Workspace.ToolOn("zapret"),"Declined start stayed green");shell.RoutineConfirmationForTests=_=>true;shell.Find<CheckBox>("ZapretCheck").IsChecked=true;await Click(shell,"ZapretCheck");Check(shell.Workspace.ToolOn("zapret")&&!shell.Settings.ZapretSelected&&shell.Settings.StartupZapret==false,"Switch rewrote participation");int count=shell.Runtime.LaunchCount;await shell.Workspace.ToggleTool("zapret",true);Check(shell.Runtime.LaunchCount==count,"Repeated on duplicated a launch");shell.Find<CheckBox>("TgCheck").IsChecked=true;await Click(shell,"TgCheck");Check(shell.Workspace.ToolOn("tg")&&!shell.Settings.TgSelected,"TG switch selected group");shell.ShowMessage("");shell.Window.UpdateLayout();TestsR2.Capture((FrameworkElement)shell.Window.Content,Path.Combine(files.Data,"r5-main-on.png"));shell.RoutineConfirmationForTests=_=>false;shell.Find<CheckBox>("ZapretCheck").IsChecked=false;await Click(shell,"ZapretCheck");Check(shell.Find<CheckBox>("ZapretCheck").IsChecked==true,"Declined stop stayed off");shell.RoutineConfirmationForTests=_=>true;shell.Find<CheckBox>("ZapretCheck").IsChecked=false;await Click(shell,"ZapretCheck");Check(!shell.Workspace.ToolOn("zapret")&&shell.Workspace.ToolOn("tg"),"Individual off stopped other stub");await shell.Runtime.Stop("tg",shell.Settings);await shell.Refresh();Check(shell.Find<CheckBox>("TgCheck").IsChecked==false,"Observed exit stayed green");shell.ShowMessage("");shell.Window.UpdateLayout();TestsR2.Capture((FrameworkElement)shell.Window.Content,Path.Combine(files.Data,"r5-main-off.png"));shell.Workspace.OpenManager();var manager=shell.Window.OwnedWindows.Cast<Window>().Single(w=>w.FindName("Groupdns")!=null);((CheckBox)manager.FindName("Groupzapret")).IsChecked=true;Check(shell.Settings.ZapretSelected&&!shell.Workspace.ToolOn("zapret")&&shell.Settings.StartupZapret==false,"Group toggle launched stub or changed startup");manager.UpdateLayout();TestsR2.Capture((FrameworkElement)manager.Content,Path.Combine(files.Data,"r5-modules.png"));manager.Close();}finally{shell.RoutineConfirmationForTests=null;await shell.StopSelected(true);shell.ApplySettings(saved);}});
  await test("R5 DNS switch applies and restores a mock adapter without changing group",async()=>{var isolated=new AppFiles(Path.Combine(files.Root,"test-results/r5-dns-switch"));using var instance=new SingleInstance(isolated.Data,isolated.Log);var fake=TestsDns.Fixture(isolated.Data);var original=fake.State;HbDnsController.ReaderForTests=fake;var preview=new Shell(isolated,true,instance);try{preview.Window.Show();preview.OpenDnsSettings();var view=(SimpleDnsView)typeof(Shell).GetField("dnsWindow",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic)!.GetValue(preview)!;view.ConfirmationForTests=_=>true;view.SelectProfile("hb:comss");await preview.Workspace.ToggleTool("dns",true);Check(preview.DnsApplied&&preview.Find<CheckBox>("DnsCheck").IsChecked==true&&!preview.Settings.Workspace.DnsInGroup&&fake.Writes>0,"DNS switch did not apply mock independently");await preview.Workspace.ToggleTool("dns",false);Check(!preview.DnsApplied&&fake.State.IPv4.Mode==NetworkHub.Dns.DnsMode.Automatic,"DNS switch did not restore original mock");view.Window.Close();}finally{preview.Dispose();preview.Window.Close();HbDnsController.ReaderForTests=null;shell.ApplySettings(shell.Settings.Copy());}});
  await test("R5 switch start UAC failure stop failure and concurrent input use observed state",async()=>{var saved=shell.Settings.Copy();try{await shell.StopSelected(true);shell.Settings.ConfirmStartStop=false;shell.Runtime.FaultForTests=(operation,id)=>operation=="start"?new System.ComponentModel.Win32Exception(1223):null;await shell.Workspace.ToggleTool("zapret",true);Check(!shell.Workspace.ToolOn("zapret")&&shell.Find<CheckBox>("ZapretCheck").IsChecked==false,"Failed launch stayed green");shell.Runtime.FaultForTests=null;int count=shell.Runtime.LaunchCount;var first=shell.Workspace.ToggleTool("zapret",true);await shell.Workspace.ToggleTool("zapret",true);await first;Check(shell.Runtime.LaunchCount==count+1,"Concurrent switch duplicated launch");shell.Runtime.FaultForTests=(operation,id)=>operation=="stop"?new IOException("Injected stop failure"):null;await shell.Workspace.ToggleTool("zapret",false);Check(shell.Find<CheckBox>("ZapretCheck").IsChecked==true,"Failed stop stayed off");}finally{shell.Runtime.FaultForTests=null;await shell.StopSelected(true);shell.ApplySettings(saved);}});
  await test("R5 settings status repair area and pinned footer remain separated at rendered DPI",()=>{var saved=shell.Settings.Copy();try{foreach(string theme in new[]{"dark","light"})foreach(string language in new[]{"ru","en"}){var next=saved.Copy();next.Theme=theme;next.Language=language;next.Backdrop="solid";shell.ApplySettings(next);var w=shell.OpenSettings();try{w.UpdateLayout();var status=(FrameworkElement)w.FindName("StartupStatusRegion");var actions=(FrameworkElement)w.FindName("SettingsActions");Check(status.TranslatePoint(new Point(0,status.ActualHeight),w).Y+15<=actions.TranslatePoint(new Point(),w).Y,"Status touches utility buttons");foreach(double scale in new[]{1d,1.25,1.5})TestsR2.Capture((FrameworkElement)w.Content,Path.Combine(files.Data,$"r5-settings-{language}-{theme}-{scale}.png"),scale);((Button)w.FindName("SettingsAdditional")).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));w.UpdateLayout();TestsR2.Capture((FrameworkElement)w.Content,Path.Combine(files.Data,$"r5-settings-expanded-{language}-{theme}.png"));}finally{w.Close();}}}finally{shell.ApplySettings(saved);}return Task.CompletedTask;});
 }
}
#endif
